// Command pattern: encapsulate request as object
interface Command {
  execute(): Promise<void>;
  undo?(): Promise<void>;  // optional — only for undoable commands
}

class TransferFundsCommand implements Command {
  constructor(
    private readonly from: AccountId,
    private readonly to: AccountId,
    private readonly amount: Money,
    private readonly ledger: LedgerService
  ) {}

  async execute(): Promise<void> {
    await this.ledger.transfer(this.from, this.to, this.amount);
  }

  async undo(): Promise<void> {
    await this.ledger.transfer(this.to, this.from, this.amount);
  }
}

