// Orchestrated saga
async function bookTrip(req: BookingRequest) {
  const hotel = await hotelService.reserve(req);
  try {
    const flight = await flightService.book(req);
    try {
      await paymentService.charge(req);
    } catch (e) {
      await flightService.cancel(flight);
      throw e;
    }
  } catch (e) {
    await hotelService.release(hotel);
    throw e;
  }
}

// Chain of Responsibility — middleware pipeline variant
type NextHandler = () => Promise<void>;
type Middleware = (ctx: RequestContext, next: NextHandler) => Promise<void>;

// Each handler calls next() to pass control down the chain
const authMiddleware: Middleware = async (ctx, next) => {
  const token = ctx.headers['authorization'];
  if (!token) throw new UnauthorizedError();
  ctx.user = await verifyToken(token);
  await next();  // pass to next handler
};

const rateLimitMiddleware: Middleware = async (ctx, next) => {
  await rateLimiter.check(ctx.user.id);
  await next();
};

const loggingMiddleware: Middleware = async (ctx, next) => {
  const start = Date.now();
  await next();
  logger.info(`${ctx.method} ${ctx.path} ${Date.now() - start}ms`);
};

// Compose into pipeline: logging wraps rate-limit wraps auth
const pipeline = compose([loggingMiddleware, rateLimitMiddleware, authMiddleware]);

// Unit of Work: track changes, flush atomically
interface UnitOfWork {
  registerNew<T>(entity: T): void;
  registerDirty<T>(entity: T): void;
  registerDeleted<T>(entity: T): void;
  commit(): Promise<void>;   // flushes all changes in one transaction
  rollback(): Promise<void>;
}

// Application service — one UoW per use case
async function placeOrder(command: PlaceOrderCommand, uow: UnitOfWork) {
  const order = Order.create(command);
  uow.registerNew(order);

  const inventory = await inventoryRepo.find(command.productId);
  inventory.reserve(command.quantity);
  uow.registerDirty(inventory);

  const ledgerEntry = LedgerEntry.forOrder(order);
  uow.registerNew(ledgerEntry);

  await uow.commit(); // all three writes in one transaction
}

